import { DataStoreProvider } from '@dhis2/app-service-datastore'
import i18n from '@dhis2/d2-i18n'
import { TabBar, Tab } from '@dhis2/ui'
import { useEffect } from 'react'
import { Outlet, useLocation, useNavigate } from 'react-router-dom'
import useExploreUri from '../../hooks/useExploreUri.js'
import exploreStore from '../../store/exploreStore.js'
import { USER_DATASTORE_NAMESPACE } from '../shared/OpenAsMapButton.jsx'
import styles from './styles/Tabs.module.css'

const getTabs = () => [
    {
        id: 'forecast10days',
        label: i18n.t('10 days forecast'),
        pointOnly: true,
    },
    { id: 'temperature', label: i18n.t('Temperature') },
    { id: 'precipitation', label: i18n.t('Precipitation') },
    { id: 'humidity', label: i18n.t('Humidity') },
    { id: 'heat', label: i18n.t('Heat') },
    { id: 'climatechange', label: i18n.t('Climate change') },
    { id: 'vegetation', label: i18n.t('Vegetation') },
    { id: 'landcover', label: i18n.t('Land cover') },
    { id: 'elevation', label: i18n.t('Elevation') },
]

const Tabs = () => {
    const { pathname } = useLocation()
    const { orgUnit, tab, setTab } = exploreStore()
    const uri = useExploreUri()
    const navigate = useNavigate()

    const isPoint = orgUnit?.geometry.type === 'Point'

    useEffect(() => {
        if (uri && uri !== pathname) {
            navigate(uri)
        }
    }, [pathname, uri, navigate])

    if (!orgUnit) {
        return null
    }

    return (
        <>
            <TabBar fixed scrollable>
                {getTabs()
                    .filter((t) => !t.pointOnly || t.pointOnly === isPoint)
                    .map(({ id, label }) => (
                        <Tab
                            key={id}
                            selected={tab === id}
                            onClick={() => setTab(id)}
                        >
                            {label}
                        </Tab>
                    ))}
            </TabBar>
            <div className={styles.tabContent}>
                <DataStoreProvider namespace={USER_DATASTORE_NAMESPACE}>
                    <Outlet />
                </DataStoreProvider>
            </div>
        </>
    )
}

export default Tabs
